_SCRIPT = """
const D=__DATA__;
const svg=document.getElementById('svg'),card=document.getElementById('card'),
  tip=document.getElementById('tip'),hl=document.getElementById('hl');
function show(i,ev){
  const it=D.items[i],b=D.bands[i];
  if(b){hl.setAttribute('y',b.y);hl.setAttribute('height',b.h);hl.style.opacity=.10;}
  tip.textContent='';
  const hd=document.createElement('b');hd.textContent=it.n&&it.n!==it.t?(it.t+' \\u00b7 '+it.n):it.t;tip.appendChild(hd);
  it.lines.forEach(function(ln){const row=document.createElement('div');
    if(ln[2]){const sw=document.createElement('s');sw.style.background='var(--'+ln[2]+')';row.appendChild(sw);}
    row.appendChild(document.createTextNode(ln[0]+'  '+ln[1]));tip.appendChild(row);});
  tip.style.opacity=1;const cr=card.getBoundingClientRect();
  tip.style.left=(ev.clientX-cr.left)+'px';tip.style.top=(ev.clientY-cr.top)+'px';
}
[...svg.querySelectorAll('.hit')].forEach(function(h){const i=+h.getAttribute('data-i');
  h.addEventListener('pointermove',function(ev){show(i,ev)});
  h.addEventListener('pointerenter',function(ev){show(i,ev)});});
svg.addEventListener('pointerleave',function(){tip.style.opacity=0;hl.style.opacity=0});
document.getElementById('tbtn').onclick=function(){const t=document.getElementById('tableview');
  t.style.display=t.style.display==='block'?'none':'block'};
document.getElementById('thm').onclick=function(){const h=document.documentElement;
  const cur=h.getAttribute('data-theme')||(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light');
  h.setAttribute('data-theme',cur==='dark'?'light':'dark')};
"""


def _safe_json(data: dict[str, Any]) -> str:
    """json.dumps hardened for inlining inside a <script> block."""
    return (
        json.dumps(data)
        .replace("<", "\\u003c")
        .replace(">", "\\u003e")
        .replace("&", "\\u0026")
        .replace(" ", "\\u2028")
        .replace(" ", "\\u2029")
    )


def document(
    *,
    title: str,
    tab: str,
    sub: str,
    hero: list[tuple[str, str, str]],
    legend: list[tuple[str, str]],
    svg_inner: str,
    svg_h: int,
    thead: list[str],
    trows: str,
    data: dict[str, Any],
) -> str:
    """Assemble the full self-contained HTML page shared by both chart forms."""

    def cv(m: str) -> str:
        return ";".join(f"--{k}:{v}" for k, v in PAL[m].items())

    style = _STYLE.replace("__L__", cv("light")).replace("__D__", cv("dark"))
    script = _SCRIPT.replace("__DATA__", _safe_json(data))
    hero_html = "".join(
        f'<div class="metric"><span class="ml">{esc(lbl)}</span>'
        f'<span class="mv {c}">{esc(val)}</span></div>'
        for lbl, val, c in hero
    )
    leg = "".join(
        f'<span class="lg"><i style="background:var(--{r})"></i>{esc(lbl)}</span>'
        for lbl, r in legend
    )
    head = "".join(f"<th>{esc(h)}</th>" for h in thead)
    return (
        f'<!doctype html><html lang="en"><head><meta charset="utf-8">'
        f'<meta name="viewport" content="width=device-width,initial-scale=1">'
        f'<title>{esc(tab)}</title><style>{style}</style></head><body><div class="wrap">'
        f'<div class="head"><div><h1>{title}</h1><div class="sub">{esc(sub)}</div></div>'
        f'<div class="hero">{hero_html}</div></div><div class="legend">{leg}</div>'
        f'<div class="card overflow" id="card"><svg id="svg" viewBox="0 0 {W} {svg_h}" '
        f'preserveAspectRatio="xMidYMid meet" role="img" aria-label="{esc(tab)}">{svg_inner}</svg>'
        f'<div class="tip" id="tip"></div></div>'
        f'<div class="barctl"><button id="tbtn">Table view</button>'
        f'<button id="thm">Toggle light/dark</button></div>'
        f'<div id="tableview" class="overflow"><table><thead><tr>{head}</tr></thead>'
        f"<tbody>{trows}</tbody></table></div></div><script>{script}</script></body></html>"
    )
